// The PDF viewer's script, moved out of pdfjs-viewer.html for the guest CSP. (Generated by scripts/build-join-site-app.js.)
let pdfJsModuleBlobUrl = "";
    let pdfJsWorkerBlobUrl = "";

    function isHttpUrl(url) {
      return String(url || "").startsWith("http://") || String(url || "").startsWith("https://");
    }

    async function importFetchedModule(moduleUrl) {
      const response = await fetch(moduleUrl, { cache: "no-store" });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const source = await response.text();
      if (pdfJsModuleBlobUrl) URL.revokeObjectURL(pdfJsModuleBlobUrl);
      pdfJsModuleBlobUrl = URL.createObjectURL(new Blob([source], { type: "text/javascript" }));
      return import(pdfJsModuleBlobUrl);
    }

    // The plain import comes first: the join site's guest copy of this page allows scripts from 'self' only, which refuses a
    // module imported from a blob: address. The fetched blob: copy is the fallback for a server with the wrong .mjs type.
    async function loadPdfJsModule(modulePath) {
      const moduleUrl = new URL(modulePath, document.baseURI || location.href).href;
      try {
        return await import(moduleUrl);
      } catch (directError) {
        try {
          return await importFetchedModule(moduleUrl);
        } catch (fallbackError) {
          console.error("[pdfjs-viewer] Failed to import PDF.js module:", directError, fallbackError);
          throw directError;
        }
      }
    }

    async function resolveWorkerUrl(workerPath) {
      const workerUrl = new URL(workerPath, document.baseURI || location.href).href;
      if (!isHttpUrl(workerUrl)) return workerUrl;
      try {
        const response = await fetch(workerUrl, { cache: "no-store" });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        // Served as JavaScript: the worker loads from its own address (a strict CSP allows workers from 'self' only).
        if (/^(text|application)\/(javascript|ecmascript|x-javascript)\b/i.test(String(response.headers.get("content-type") || "").trim())) {
          try { response.body?.cancel?.().catch?.(() => {}); } catch (_) {}
          return workerUrl;
        }
        const source = await response.text();
        if (pdfJsWorkerBlobUrl) URL.revokeObjectURL(pdfJsWorkerBlobUrl);
        pdfJsWorkerBlobUrl = URL.createObjectURL(new Blob([source], { type: "text/javascript" }));
        return pdfJsWorkerBlobUrl;
      } catch (error) {
        console.warn("[pdfjs-viewer] Falling back to direct PDF.js worker URL:", error);
        return workerUrl;
      }
    }

    // The engine load runs before the rest of the boot: a failure here used to leave the toolbar
    // on "Loading..." forever. Remember it and surface it below, where #status exists.
    let pdfjsLib = null;
    try {
      pdfjsLib = await loadPdfJsModule("./node_modules/pdfjs-dist/build/pdf.mjs");
      pdfjsLib.GlobalWorkerOptions.workerSrc = await resolveWorkerUrl("./node_modules/pdfjs-dist/build/pdf.worker.mjs");
    } catch (error) {
      console.error("[pdfjs-viewer] Failed to load the PDF engine:", error);
    }

    const params = new URLSearchParams(location.search);
    // No default document: the app opens this page with ?src= (a blob: address on the guest
    // page). A bare visit has nothing to show, and the old fallback named a file that never shipped.
    const pdfUrl = params.get("src") || "";
    const titleText = params.get("title") || "PDF Preview";
    const status = document.getElementById("status");
    const viewer = document.getElementById("viewer");
    const pages = document.getElementById("pages");
    const thumbnails = document.getElementById("thumbnails");
    const pageNumberInput = document.getElementById("pageNumber");
    const pageCountValue = document.getElementById("pageCountValue");
    const zoomReadout = document.getElementById("zoomReadout");
    const sidebarToggle = document.getElementById("sidebarToggle");
    const zoomOutButton = document.getElementById("zoomOut");
    const zoomInButton = document.getElementById("zoomIn");
    const fitWidthButton = document.getElementById("fitWidth");
    const rotateButton = document.getElementById("rotatePdf");
    const downloadButton = document.getElementById("downloadPdf");
    const printButton = document.getElementById("printPdf");
    const moreButton = document.getElementById("moreButton");
    const moreMenu = document.getElementById("moreMenu");
    const deviceScale = Math.min(window.devicePixelRatio || 1, 2);

    let pdfDocument = null;
    let resolvedPdfUrl = "";
    let pdfBlob = null;
    let renderToken = 0;
    let thumbnailToken = 0;
    let activeRenderTask = null;
    let activeThumbnailTask = null;
    let currentPage = 1;
    let zoomMultiplier = 1;
    let currentRotation = 0;

    document.title = titleText;

    function normalizeStoredBlobRecord(value) {
      if (value instanceof Blob) return value;
      if (value && value.blob instanceof Blob) return value.blob;
      if (value && value.data instanceof Blob) return value.data;
      if (value && value.file instanceof Blob) return value.file;
      return value;
    }

    function openFlowJoeImageDb() {
      return new Promise((resolve, reject) => {
        const request = indexedDB.open("flowjoe-images");
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error || new Error("Unable to open media database"));
      });
    }

    async function getIndexedDbPdfBlob(src) {
      const key = String(src || "").replace(/^indexeddb:/, "").trim();
      if (!key) return null;
      const db = await openFlowJoeImageDb();
      return new Promise((resolve, reject) => {
        const tx = db.transaction("images", "readonly");
        const store = tx.objectStore("images");
        const request = store.get(key);
        request.onsuccess = () => resolve(normalizeStoredBlobRecord(request.result));
        request.onerror = () => reject(request.error || new Error("Unable to read PDF"));
      });
    }

    // The join site's copy of this page is a guest page (scripts/build-join-site-app.js adds the guest marker): a guest's viewer
    // is handed the PDF as a blob: address and never opens the browser's IndexedDB.
    const isGuestViewer = !!document.querySelector('meta[name="flowjoe-profile"][content="guest"]');

    async function resolvePdfSource(src) {
      const normalized = String(src || "").trim();
      if (normalized.startsWith("indexeddb:") && isGuestViewer) throw new Error("A shared PDF opens from the guest page, not from local media storage");
      if (normalized.startsWith("indexeddb:")) {
        const blob = await getIndexedDbPdfBlob(normalized);
        if (!blob) throw new Error("PDF was not found in local media storage");
        pdfBlob = blob.type ? blob : new Blob([blob], { type: "application/pdf" });
        return URL.createObjectURL(pdfBlob);
      }
      if (normalized.startsWith("blob:")) {
        const response = await fetch(normalized);
        pdfBlob = await response.blob();
        return normalized;
      }
      return normalized;
    }

    function pageFitWidth() {
      return Math.max(280, viewer.clientWidth);
    }

    function getScaleForPage(baseViewport) {
      return (pageFitWidth() / baseViewport.width) * zoomMultiplier;
    }

    function updateZoomReadout() {
      zoomReadout.textContent = Math.abs(zoomMultiplier - 1) < 0.01
        ? "Fit"
        : `${Math.round(zoomMultiplier * 100)}%`;
    }

    function setStatus(text) {
      status.textContent = text || "";
    }

    function setCurrentPage(pageNumber) {
      const bounded = Math.min(Math.max(1, Number(pageNumber) || 1), pdfDocument?.numPages || 1);
      currentPage = bounded;
      pageNumberInput.value = String(bounded);
      thumbnails.querySelectorAll(".thumbnail").forEach((thumb) => {
        thumb.classList.toggle("active", Number(thumb.dataset.pageNumber || 0) === bounded);
      });
    }

    async function renderPage(pdf, pageIndex, token) {
      const page = await pdf.getPage(pageIndex);
      if (token !== renderToken) return;
      const baseViewport = page.getViewport({ scale: 1, rotation: currentRotation });
      const scale = getScaleForPage(baseViewport);
      const viewport = page.getViewport({ scale, rotation: currentRotation });
      const canvas = document.createElement("canvas");
      canvas.className = "page";
      canvas.dataset.pageNumber = String(pageIndex);
      canvas.width = Math.max(1, Math.floor(viewport.width * deviceScale));
      canvas.height = Math.max(1, Math.floor(viewport.height * deviceScale));
      canvas.style.width = `${Math.floor(viewport.width)}px`;
      canvas.style.height = `${Math.floor(viewport.height)}px`;
      pages.appendChild(canvas);
      const task = page.render({
        canvasContext: canvas.getContext("2d", { alpha: false }),
        viewport,
        transform: deviceScale === 1 ? null : [deviceScale, 0, 0, deviceScale, 0, 0]
      });
      activeRenderTask = task;
      try {
        await task.promise;
      } finally {
        if (activeRenderTask === task) activeRenderTask = null;
      }
    }

    function cancelActiveRender() {
      if (activeRenderTask && typeof activeRenderTask.cancel === "function") {
        try {
          activeRenderTask.cancel();
        } catch (_) {
          /* already finished */
        }
      }
      activeRenderTask = null;
    }

    function cancelActiveThumbnailRender() {
      if (activeThumbnailTask && typeof activeThumbnailTask.cancel === "function") {
        try {
          activeThumbnailTask.cancel();
        } catch (_) {
          /* already finished */
        }
      }
      activeThumbnailTask = null;
    }

    async function renderThumbnail(pdf, pageIndex) {
      const page = await pdf.getPage(pageIndex);
      const baseViewport = page.getViewport({ scale: 1, rotation: currentRotation });
      const scale = 104 / baseViewport.width;
      const viewport = page.getViewport({ scale, rotation: currentRotation });
      const button = document.createElement("button");
      button.type = "button";
      button.className = "thumbnail";
      button.dataset.pageNumber = String(pageIndex);
      button.setAttribute("aria-label", `Go to page ${pageIndex}`);
      const canvas = document.createElement("canvas");
      canvas.width = Math.max(1, Math.floor(viewport.width * deviceScale));
      canvas.height = Math.max(1, Math.floor(viewport.height * deviceScale));
      canvas.style.width = `${Math.floor(viewport.width)}px`;
      canvas.style.height = `${Math.floor(viewport.height)}px`;
      const label = document.createElement("div");
      label.className = "thumbnail-label";
      label.textContent = String(pageIndex);
      button.append(canvas, label);
      button.addEventListener("click", () => scrollToPage(pageIndex));
      thumbnails.appendChild(button);
      const task = page.render({
        canvasContext: canvas.getContext("2d", { alpha: false }),
        viewport,
        transform: deviceScale === 1 ? null : [deviceScale, 0, 0, deviceScale, 0, 0]
      });
      activeThumbnailTask = task;
      try {
        await task.promise;
      } finally {
        if (activeThumbnailTask === task) activeThumbnailTask = null;
      }
    }

    async function renderDocument({ preservePage = currentPage } = {}) {
      if (!pdfDocument) return;
      const token = ++renderToken;
      cancelActiveRender();
      pages.replaceChildren();
      setStatus("Rendering...");
      try {
        for (let pageIndex = 1; pageIndex <= pdfDocument.numPages; pageIndex += 1) {
          if (token !== renderToken) return;
          setStatus(`Rendering ${pageIndex} / ${pdfDocument.numPages}`);
          await renderPage(pdfDocument, pageIndex, token);
        }
      } catch (error) {
        if (token !== renderToken) return; // a newer render superseded (or cancelled) this one
        console.error("[pdfjs-viewer] Failed to render the document:", error);
        setStatus("PDF preview failed");
        return;
      }
      if (token !== renderToken) return;
      setStatus("");
      scrollToPage(preservePage, { behavior: "auto" });
      updateCurrentPageFromScroll();
    }

    async function renderThumbnails(pdf) {
      const token = ++thumbnailToken;
      cancelActiveThumbnailRender();
      thumbnails.replaceChildren();
      try {
        for (let pageIndex = 1; pageIndex <= pdf.numPages; pageIndex += 1) {
          if (token !== thumbnailToken) return;
          await renderThumbnail(pdf, pageIndex);
        }
      } catch (error) {
        if (token !== thumbnailToken) return; // a newer pass superseded (or cancelled) this one
        console.error("[pdfjs-viewer] Failed to render thumbnails:", error);
      }
    }

    function scrollToPage(pageIndex, options = {}) {
      const page = pages.querySelector(`.page[data-page-number="${pageIndex}"]`);
      if (!page) return;
      viewer.scrollTo({
        top: page.offsetTop - 12,
        behavior: options.behavior || "smooth"
      });
      setCurrentPage(pageIndex);
    }

    function updateCurrentPageFromScroll() {
      const canvases = Array.from(pages.querySelectorAll(".page"));
      if (!canvases.length) return;
      const marker = viewer.scrollTop + Math.max(80, viewer.clientHeight * 0.28);
      let bestPage = 1;
      let bestDistance = Infinity;
      for (const canvas of canvases) {
        const pageTop = canvas.offsetTop;
        const pageBottom = pageTop + canvas.offsetHeight;
        const distance = marker < pageTop
          ? pageTop - marker
          : marker > pageBottom
            ? marker - pageBottom
            : 0;
        if (distance < bestDistance) {
          bestDistance = distance;
          bestPage = Number(canvas.dataset.pageNumber || 1);
        }
      }
      setCurrentPage(bestPage);
    }

    function setZoomMultiplier(nextZoom) {
      const numericZoom = Number(nextZoom);
      zoomMultiplier = Math.min(4, Math.max(0.25, Number.isFinite(numericZoom) ? numericZoom : 1));
      updateZoomReadout();
      renderDocument({ preservePage: currentPage });
    }

    async function getDownloadBlob() {
      if (pdfBlob) return pdfBlob;
      const response = await fetch(resolvedPdfUrl || pdfUrl);
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      return response.blob();
    }

    sidebarToggle.addEventListener("click", () => {
      document.body.classList.toggle("sidebar-open");
      sidebarToggle.classList.toggle("is-active", document.body.classList.contains("sidebar-open"));
      renderDocument({ preservePage: currentPage });
    });

    pageNumberInput.addEventListener("change", () => scrollToPage(Number(pageNumberInput.value || 1)));
    pageNumberInput.addEventListener("keydown", (event) => {
      if (event.key !== "Enter") return;
      event.preventDefault();
      scrollToPage(Number(pageNumberInput.value || 1));
    });

    zoomOutButton.addEventListener("click", () => setZoomMultiplier(zoomMultiplier / 1.2));
    zoomInButton.addEventListener("click", () => setZoomMultiplier(zoomMultiplier * 1.2));
    fitWidthButton.addEventListener("click", () => setZoomMultiplier(1));
    rotateButton.addEventListener("click", async () => {
      if (!pdfDocument) return;
      currentRotation = (currentRotation + 90) % 360;
      await Promise.all([
        renderDocument({ preservePage: currentPage }),
        renderThumbnails(pdfDocument)
      ]);
    });

    viewer.addEventListener("scroll", () => requestAnimationFrame(updateCurrentPageFromScroll), { passive: true });
    let resizeTimer = null;
    window.addEventListener("resize", () => {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        resizeTimer = null;
        renderDocument({ preservePage: currentPage });
      }, 150);
    });

    downloadButton.addEventListener("click", async () => {
      try {
        const blob = await getDownloadBlob();
        const url = URL.createObjectURL(blob);
        const anchor = document.createElement("a");
        anchor.href = url;
        anchor.download = titleText || "document.pdf";
        anchor.click();
        setTimeout(() => URL.revokeObjectURL(url), 2000);
      } catch (error) {
        console.error("[pdfjs-viewer] Download failed:", error);
        setStatus("PDF download failed");
      }
    });
    printButton.addEventListener("click", () => window.print());
    moreButton.addEventListener("click", (event) => {
      event.stopPropagation();
      const nextOpen = moreButton.dataset.open !== "true";
      moreButton.dataset.open = nextOpen ? "true" : "false";
      moreMenu.style.display = nextOpen ? "block" : "none";
    });
    moreMenu.addEventListener("click", (event) => {
      const action = event.target?.closest?.("[data-more-action]")?.dataset?.moreAction;
      if (!action) return;
      moreButton.dataset.open = "false";
      moreMenu.style.display = "none";
      if (action === "download") downloadButton.click();
      if (action === "print") printButton.click();
    });
    document.addEventListener("click", () => {
      moreButton.dataset.open = "false";
      moreMenu.style.display = "none";
    });

    if (!pdfjsLib) {
      setStatus("PDF preview failed");
    } else if (!pdfUrl) {
      setStatus("No document to show");
    } else {
      try {
        resolvedPdfUrl = await resolvePdfSource(pdfUrl);
        pdfDocument = await pdfjsLib.getDocument(resolvedPdfUrl).promise;
        pageCountValue.textContent = String(pdfDocument.numPages);
        pageNumberInput.dataset.max = String(pdfDocument.numPages);
        updateZoomReadout();
        setCurrentPage(1);
        await Promise.all([
          renderDocument({ preservePage: 1 }),
          renderThumbnails(pdfDocument)
        ]);
        // No setStatus("") here: renderDocument clears the status itself on success, and a render
        // failure it caught must keep its "PDF preview failed" instead of being erased right after
        // being reported.
      } catch (error) {
        console.error(error);
        setStatus("PDF preview failed");
      }
    }
